package com.vandorlabs.neoforge.legacylanding.client;
import com.mojang.blaze3d.vertex.*;
import com.mojang.math.Axis;
import com.vandorlabs.gear.core.*;
import com.vandorlabs.neoforge.NativeLegacyLandingModels;
import com.vandorlabs.neoforge.legacylanding.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.blockentity.*;
import net.minecraft.client.renderer.texture.TextureAtlas;
import net.minecraft.core.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.phys.AABB;
/** Authored stationary parts and Source's repeating piston UVs, using the pause-aware received pose. */
public final class NativeLegacyLandingRenderer implements BlockEntityRenderer<NativeLegacyLandingEntity>{
 public NativeLegacyLandingRenderer(BlockEntityRendererProvider.Context context){}
 @Override public void render(NativeLegacyLandingEntity tile,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){if(tile.getLevel()==null||tile.inert()||!tile.physicalRoot())return;double progress=NativeLegacyVisualClock.pose(tile);int size=tile.settings().size();String prefix=tile.kind().id+"_"+NativeLegacyLandingModels.SIZES[Math.min(3,size)];var buffer=buffers.getBuffer(RenderType.cutout());poses.pushPose();try{double center=.5+(size==4?.5:0);poses.translate(center,0,center);poses.mulPose(Axis.YP.rotationDegrees(180-tile.getBlockState().getValue(NativeLegacyLandingBlock.FACING).toYRot()));poses.translate(-.5,0,-.5);draw(prefix+"_fixed",poses,buffer,light,overlay);poses.pushPose();poses.translate(0,-progress,0);draw(prefix+"_wheel",poses,buffer,light,overlay);if(tile.kind().ski){if(!connected(tile,true))draw(prefix+"_nose_front",poses,buffer,light,overlay);if(!connected(tile,false))draw(prefix+"_nose_rear",poses,buffer,light,overlay);}poses.popPose();piston(poses,buffer,light,overlay,LegacyLandingSettings.pistonAnchor(size),LegacyLandingSettings.pistonAnchor(size)-LegacyLandingSettings.pistonLength(size)-progress,size>=3&&!tile.kind().nonWheeled);}finally{poses.popPose();}}
 private static boolean connected(NativeLegacyLandingEntity tile,boolean front){var state=tile.getBlockState();var facing=state.getValue(NativeLegacyLandingBlock.FACING);var next=tile.getBlockPos().relative(front?facing:facing.getOpposite(),tile.settings().size()==4?2:1);if(!NativeLegacyLandingBlock.loaded(tile.getLevel(),next))return false;var other=NativeLegacyLandingBlock.owner(tile.getLevel(),next);return other!=null&&LegacyLandingLayout.connectedEnd(true,other.kind()==tile.kind(),tile.settings().size(),other.settings().size(),facing.get2DDataValue(),other.getBlockState().getValue(NativeLegacyLandingBlock.FACING).get2DDataValue(),tile.progress(),other.progress());}
 private static void draw(String name,PoseStack poses,VertexConsumer buffer,int light,int overlay){for(var quad:NativeLegacyLandingModels.quads(name)){var n=quad.getDirection();float shade=n.getAxis()==Direction.Axis.Y?(n==Direction.UP?1:.5F):n.getAxis()==Direction.Axis.X?.6F:.8F;buffer.putBulkData(poses.last(),quad,shade,shade,shade,1,light,overlay);}}
 private static void piston(PoseStack poses,VertexConsumer b,int light,int overlay,double top,double bottom,boolean large){var sprite=Minecraft.getInstance().getTextureAtlas(TextureAtlas.LOCATION_BLOCKS).apply(ResourceLocation.parse("vandorlabs:frame-default/metal_side"));double low=large?.25:.375,high=large?.75:.625;for(double upper=top;upper>bottom+1E-8;upper-=1){double lower=Math.max(bottom,upper-1),v=upper-lower;quad(poses,b,sprite,light,overlay,Direction.NORTH,low,upper,low,high,upper,low,high,lower,low,low,lower,low,.375,0,.625,v);quad(poses,b,sprite,light,overlay,Direction.SOUTH,high,upper,high,low,upper,high,low,lower,high,high,lower,high,.375,0,.625,v);quad(poses,b,sprite,light,overlay,Direction.WEST,low,upper,high,low,upper,low,low,lower,low,low,lower,high,.375,0,.625,v);quad(poses,b,sprite,light,overlay,Direction.EAST,high,upper,low,high,upper,high,high,lower,high,high,lower,low,.375,0,.625,v);}quad(poses,b,sprite,light,overlay,Direction.UP,low,top,high,high,top,high,high,top,low,low,top,low,.375,.375,.625,.625);quad(poses,b,sprite,light,overlay,Direction.DOWN,low,bottom,low,high,bottom,low,high,bottom,high,low,bottom,high,.375,.375,.625,.625);}
 private static void quad(PoseStack p,VertexConsumer b,net.minecraft.client.renderer.texture.TextureAtlasSprite s,int light,int overlay,Direction n,double x0,double y0,double z0,double x1,double y1,double z1,double x2,double y2,double z2,double x3,double y3,double z3,double u0,double v0,double u1,double v1){vertex(p,b,s,light,overlay,n,x0,y0,z0,u0,v0);vertex(p,b,s,light,overlay,n,x1,y1,z1,u1,v0);vertex(p,b,s,light,overlay,n,x2,y2,z2,u1,v1);vertex(p,b,s,light,overlay,n,x3,y3,z3,u0,v1);}
 private static void vertex(PoseStack p,VertexConsumer b,net.minecraft.client.renderer.texture.TextureAtlasSprite s,int light,int overlay,Direction n,double x,double y,double z,double u,double v){float shade=n.getAxis()==Direction.Axis.Y?(n==Direction.UP?1:.5F):n.getAxis()==Direction.Axis.X?.6F:.8F;b.addVertex(p.last().pose(),(float)x,(float)y,(float)z).setColor(shade,shade,shade,1).setUv(s.getU((float)u),s.getV((float)v)).setLight(light).setOverlay(overlay).setNormal(p.last(),n.getStepX(),n.getStepY(),n.getStepZ());}
 @Override public AABB getRenderBoundingBox(NativeLegacyLandingEntity tile){return new AABB(tile.getBlockPos()).inflate(2,5,2);}
 @Override public int getViewDistance(){return 128;}
}
